mapper.sql:
select project.PROJECT_ID, project.SOU_NO, project.SOU_NAME, project.PROJECT_STATUS, case when vendor_score_info.NEED_TECH_SCORE_VENDOR_COUNT = score_info.HAS_SCORE_VENDOR_COUNT then 'FINISHED' else 'UNFINISHED' end score_status, project.score_rule_type, project.current_round, project.created_by, project.created_full_name, project.creation_date, project.publish_time, project.order_end_time from scc_sou_project project left join scc_sou_process_config process_config on process_config.PROCESS_CONFIG_ID = project.PROCESS_CONFIG_ID left join scc_sou_group sou_group on project.PROJECT_ID = sou_group.PROJECT_ID and sou_group.SCORE_AUTH like '%SOU_TECH%' left join ( -- 查询应评分供应商数量(用于判断评分人员维度的评分状态) select a.PROJECT_ID, ifnull(count(a.VENDOR_COUNT),0) need_tech_score_vendor_count from ( select sou_order.PROJECT_ID, count(sou_order.VENDOR_ID) vendor_count from scc_sou_order sou_order where ORDER_STATUS = 'SUBMISSION' group by PROJECT_ID, VENDOR_ID) a group by a.PROJECT_ID ) vendor_score_info on project.PROJECT_ID = vendor_score_info.PROJECT_ID left join ( -- 查询已评分供应商数量(用于判断评分人员维度的评分状态) select PROJECT_ID, GROUP_ID, ifnull(count(GROUP_ID),0) has_score_vendor_count from scc_sou_tech_score_head where SCORE_STATUS = 'FINISHED' group by PROJECT_ID, GROUP_ID) score_info on project.PROJECT_ID = score_info.PROJECT_ID and sou_group.GROUP_ID = score_info.GROUP_ID where exists ( select process_config.PROCESS_CONFIG_ID from scc_sou_process_config process_config where process_config.PROCESS_CONFIG_ID = project.PROCESS_CONFIG_ID and process_config.TECH_MANAGEMENT = 'Y' ) and project.TECH_OPEN = 'Y' AND sou_group.USER_ID = #{queryParam.currentUserId} and project.SOU_TYPE = #{souType}
AND project.SOU_NO like concat('%', concat(#{queryParam.souNo}, '%'))
AND project.SOU_NAME like concat('%', concat(#{queryParam.souName}, '%'))
AND project.PROJECT_STATUS = #{queryParam.projectStatus}
AND project.SCORE_RULE_TYPE = #{queryParam.scoreRuleType}
AND project.CREATED_BY = #{queryParam.createdBy}
AND score_head.SCORE_STATUS = #{queryParam.scoreStatus}
AND project.CREATION_DATE >= #{queryParam.creationDateFrom}
AND project.CREATION_DATE <= #{queryParam.creationDateTo}
AND project.PUBLISH_TIME >= #{queryParam.publishTimeFrom}
AND project.PUBLISH_TIME <= #{queryParam.publishTimeTo}
AND project.ORDER_END_TIME >= #{queryParam.orderEndTimeFrom}
AND project.ORDER_END_TIME <= #{queryParam.orderEndTimeTo}
order by project.SOU_NO desc
